var n=`0140-khorovats`;var t=`world-0140`;var r=`AM`;var o=`western-asia`;var a=4;var s=74;var l={en:`Khorovats`,ua:`Хоровац`};var g={en:`A classic dish from Armenia, featuring pork shoulder, yellow onion, tomato, red bell pepper. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Вірменія. Основні складники: свиняча лопатка, жовта цибуля, помідор, червоний солодкий перець. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 35 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 35 хвилин.`,t:[`marinating`],m:35,i:[[`pork-shoulder`,850,`g`],[`yellow-onion`,230,`g`],[`extra-virgin-olive-oil`,45,`ml`],[`lemon-juice`,40,`ml`],[`ground-black-pepper`,null,`to_taste`],[`table-salt`,null,`to_taste`]]},{en:`Thread the prepared pieces onto skewers, leaving small gaps to ensure even cooking.`,ua:`Нанизайте підготовлені шматочки на шампури чи шпажки, залишаючи невеликі проміжки для рівномірного приготування.`,t:[`threading-skewers`],m:12,i:[]},{en:`Grill over medium-high heat for about 25 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 25 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:25,i:[[`tomato`,250,`g`],[`red-bell-pepper`,220,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`parsley`,25,`g`]]}];var u={slug:n,id:t,country:`AM`,region:o,servings:4,minutes:74,title:l,text:g,steps:d};export{r as country,u as default,t as id,s as minutes,o as region,a as servings,n as slug,d as steps,g as text,l as title};